default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\Software\Microsoft\Windows\Currentversion\Policies\System' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('LegalNoticeCaption', $null, 'DoNotExpandEnvironmentNames') }
$kind = $null
if ($null -ne $current) { $kind = $key.GetValueKind('LegalNoticeCaption') }
if (-not ($current -is [string] -and $kind -ceq 'String' -and $current -ceq '$ODV_legal_notice_caption')) {
    Write-Output 'Mismatch: HKLM:\Software\Microsoft\Windows\Currentversion\Policies\System [LegalNoticeCaption]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\Software\Microsoft\Windows\Currentversion\Policies\System')) {
    New-Item -Path 'HKLM:\Software\Microsoft\Windows\Currentversion\Policies\System' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\Software\Microsoft\Windows\Currentversion\Policies\System' -Name 'LegalNoticeCaption' -Value '$ODV_legal_notice_caption' -PropertyType String -Force | Out-Null
exit 0
